// =========================================================================
// Node I/O Example Tests
// =========================================================================

// These tests verify individual node behavior against specified examples.
// Each test executes a single node with given inputs and checks outputs.

/// Node example: prepare_scan_workspace - Prepares a workspace scan transport request
/// 
/// Tests that node 'prepare_scan_workspace' produces expected outputs for given inputs.
#[test]
fn test_example_prepare_scan_workspace_prepares_a_workspace_scan_transport_request() {
    let dag = crate :: build_bootstrap_graph().unwrap();
    let inputs = std::collections::HashMap::new();
    let outputs = gunbc_exec::execute_single_node(&dag, "prepare_scan_workspace", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'prepare_scan_workspace' should execute successfully");

    // Check output port 'request'
    let output_request = outputs.get("request").expect("output port 'request' should exist");
    assert!(!output_request.is_empty(), "expected non-empty value");
}

/// Node example: parse_scan_result - Parses shell stdout to extract sorted crate names and count
/// 
/// Tests that node 'parse_scan_result' produces expected outputs for given inputs.
#[test]
fn test_example_parse_scan_result_parses_shell_stdout_to_extract_sorted_crate_names_and_count() {
    let dag = crate :: build_bootstrap_graph().unwrap();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("response".to_string(), Value::Response(gunbc_ir::transport::TransportResponse::Shell(gunbc_ir::transport::ShellResponse { exit_code: 0, stdout: "crates/bar
crates/foo
".to_string(), stderr: "".to_string() })));
    let outputs = gunbc_exec::execute_single_node(&dag, "parse_scan_result", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'parse_scan_result' should execute successfully");

    // Check output port 'crate_count'
    let output_crate_count = outputs.get("crate_count").expect("output port 'crate_count' should exist");
    assert_eq!(*output_crate_count, Value::Int(2), "expected exact value");
    // Check output port 'crate_names'
    let output_crate_names = outputs.get("crate_names").expect("output port 'crate_names' should exist");
    assert_eq!(*output_crate_names, Value::List(vec![Value::Str("bar".to_string()), Value::Str("foo".to_string())]), "expected exact value");
}

/// Node example: parse_scan_result - Handles skipped transport response gracefully
/// 
/// Tests that node 'parse_scan_result' produces expected outputs for given inputs.
